(1197621, 151131, 16648, '<td valign="top">A miss-take on the challenge. Don;t take a pic of a billboard, but a pic that could BE a billboard.</td>', 'A miss-take on the challenge. Don;t take a pic of a billboard, but a pic that could BE a billboard.', '2005-02-28 00:58:18.000000', NULL, 1),
(1197623, 150591, 31213, '<td valign="top">My biggest complaint is that the dimentions are not 640X320 like everyone elses.  Also wish the sharpness of the chord was a bit better.  Now that I got all that negativity out...this is a great imitation of one of their ads!  Nice job.  Very pleasant composition.  :))</td>', 'My biggest complaint is that the dimentions are not 640X320 like everyone elses.  Also wish the sharpness of the chord was a bit better.  Now that I got all that negativity out...this is a great imitation of one of their ads!  Nice job.  Very pleasant composition.  :))', '2005-02-28 00:58:35.000000', NULL, 1),
