(1198048, 150921, 30861, '<td valign="top">Rich and luscious. Good negative space for text. One thing, though; typically, a billboard will run text flush right, so the image leads into the text, so I''d have dlipped this horizontally... Very strong entry.</td>', 'Rich and luscious. Good negative space for text. One thing, though; typically, a billboard will run text flush right, so the image leads into the text, so I''d have dlipped this horizontally... Very strong entry.', '2005-02-28 03:28:58.000000', NULL, 1),
(1198050, 151122, 30861, '<td valign="top">Gorgeous shot, but you haven''t allowed space for text on the billboard. I also wish we could see more of the bottom lip. Strong entry.</td>', 'Gorgeous shot, but you haven''t allowed space for text on the billboard. I also wish we could see more of the bottom lip. Strong entry.', '2005-02-28 03:30:13.000000', NULL, 1),
(1198051, 150703, 30861, '<td valign="top">There''s an uneasy balance between harsh contrast and soft focus in this image. i wish you''d used some USM. Also, for a billboard, it''s usually better to have the image leading into the text, so I''d have flipped the shot horizontally myself. Strong entry.</td>', 'There''s an uneasy balance between harsh contrast and soft focus in this image. i wish you''d used some USM. Also, for a billboard, it''s usually better to have the image leading into the text, so I''d have flipped the shot horizontally myself. Strong entry.', '2005-02-28 03:32:02.000000', NULL, 1),
