(1200146, 150689, 10080, '<td valign="top">Its really a nice shot, but the lean to the right really throws it off. The colors and lighting are nice.8</td>', 'Its really a nice shot, but the lean to the right really throws it off. The colors and lighting are nice.8', '2005-02-28 22:16:38.000000', NULL, 1),
(1200147, 150798, 28141, '<td valign="top">Advertisers wouldn''t waste billboard space on a border.  Things need to be as big as possible to get noticed by drivers.  Great concept though and the shot it self is well composed.</td>', 'Advertisers wouldn''t waste billboard space on a border.  Things need to be as big as possible to get noticed by drivers.  Great concept though and the shot it self is well composed.', '2005-02-28 22:16:42.000000', NULL, 1),
