(1200854, 150884, 28141, '<td valign="top">Cutting off the text at the bottom of the sign is a little unsettling.  Need to shoot from a higher angle.</td>', 'Cutting off the text at the bottom of the sign is a little unsettling.  Need to shoot from a higher angle.', '2005-03-01 10:42:32.000000', NULL, 1),
(1200857, 150703, 28141, '<td valign="top">Great shot, but they sell clothes, right?  I think you need to show a little more of the clothes in addition to the face to make it effective at advertising the clothes.</td>', 'Great shot, but they sell clothes, right?  I think you need to show a little more of the clothes in addition to the face to make it effective at advertising the clothes.', '2005-03-01 10:44:42.000000', NULL, 1),
(1200861, 151107, 28141, '<td valign="top">For this to be effective, I think you need to be able to see all of the sign on the building and read it quickley (i.e. while driving by).  At this angle, that''s difficult.</td>', 'For this to be effective, I think you need to be able to see all of the sign on the building and read it quickley (i.e. while driving by).  At this angle, that''s difficult.', '2005-03-01 10:46:57.000000', NULL, 1),
(1200862, 150996, 28141, '<td valign="top">The challenge was to take a photo that could serve as a billboard advertisement, not to take a photo of an existing billboard.</td>', 'The challenge was to take a photo that could serve as a billboard advertisement, not to take a photo of an existing billboard.', '2005-03-01 10:47:45.000000', NULL, 1),
(1200867, 150440, 28141, '<td valign="top">Would like to see the kiss print in focus, or at least closer to focused.</td>', 'Would like to see the kiss print in focus, or at least closer to focused.', '2005-03-01 10:50:06.000000', NULL, 1),
(1200868, 150402, 28141, '<td valign="top">I''m assuming from the title that she''s supposed to be sunbathing on snow, but I can''t tell if it''s snow or sand in the picture.</td>', 'I''m assuming from the title that she''s supposed to be sunbathing on snow, but I can''t tell if it''s snow or sand in the picture.', '2005-03-01 10:52:06.000000', NULL, 1),
(1200870, 150728, 28141, '<td valign="top">A subject needs to stand out in a billboard advertisement.  I like this shot, but I don''t think a passing driver would have time to see anything but the chainlink fence.</td>', 'A subject needs to stand out in a billboard advertisement.  I like this shot, but I don''t think a passing driver would have time to see anything but the chainlink fence.', '2005-03-01 10:54:06.000000', NULL, 1),
