(1200921, 150912, 28141, '<td valign="top">The challenge was to take a photo that could serve as a billboard advertisement, not to take a photo of an existing billboard.</td>', 'The challenge was to take a photo that could serve as a billboard advertisement, not to take a photo of an existing billboard.', '2005-03-01 12:08:12.000000', NULL, 1),
