(1201006, 150502, 17033, '<td valign="top">Not sure about the use of ''aching'' but great advertising shot. Only criticism is that it could do with some extra spots of light : it looks a bit flat at the moment</td>', 'Not sure about the use of ''aching'' but great advertising shot. Only criticism is that it could do with some extra spots of light : it looks a bit flat at the moment', '2005-03-01 13:08:43.000000', NULL, 1),
(1201012, 150440, 17033, '<td valign="top">Took me a while to figure out the background. I think advertising people tend to sell the image/lifestyle rather than the product itself in these cases.....the lipstick container isn''t particularly attractive whereas the woman applying it would have to be</td>', 'Took me a while to figure out the background. I think advertising people tend to sell the image/lifestyle rather than the product itself in these cases.....the lipstick container isn''t particularly attractive whereas the woman applying it would have to be', '2005-03-01 13:12:05.000000', NULL, 1),
(1201015, 150792, 17033, '<td valign="top">If you cropped to remove the grey table you could perhaps convince the viewer that the trains are real. More of a head-on shot or with them  diverging towards you would give the impression of speed which is what  they may be looking  for.</td>', 'If you cropped to remove the grey table you could perhaps convince the viewer that the trains are real. More of a head-on shot or with them  diverging towards you would give the impression of speed which is what  they may be looking  for.', '2005-03-01 13:15:47.000000', NULL, 1),
(1201043, 150587, 17033, '<td valign="top">Much better without sign</td>', 'Much better without sign', '2005-03-01 13:33:03.000000', NULL, 1),
