(1207662, 150653, 12571, '<td valign="top">I would have liked this better if the flowers had been real, nevertheless, I like the light off the glass and the colours</td>', 'I would have liked this better if the flowers had been real, nevertheless, I like the light off the glass and the colours', '2005-03-04 14:14:40.000000', NULL, 1),
(1207674, 150384, 30364, '<td valign="top">Terrific photograph.  The title is the right sentiment but too long for a billboard.  "Who''s had their flu shot?" or something like it, would work better. Also a bit hard to figure out where the words would go on the billboard.  However, I have not marked this excellent entry down for that, because this is about the image, and yours is very good.  8</td>', 'Terrific photograph.  The title is the right sentiment but too long for a billboard.  "Who''s had their flu shot?" or something like it, would work better. Also a bit hard to figure out where the words would go on the billboard.  However, I have not marked this excellent entry down for that, because this is about the image, and yours is very good.  8', '2005-03-04 14:27:24.000000', NULL, 1),
(1207679, 151128, 30364, '<td valign="top">Good photograph, unworkable title (for a billboard slogan).  But the image is really striking.  7</td>', 'Good photograph, unworkable title (for a billboard slogan).  But the image is really striking.  7', '2005-03-04 14:31:22.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1207695, 150563, 30364, '<td valign="top">This is a great shot, well composed &amp; cropped to capture the "Don''t tread on me!" character of this awesome little machine.  Of course, adding the text would probably ruin the look of your image, but it would still be a terrific billboard with no text at all, and the word  "SUBARU" made just a little more prominent.  But this challenge is just about the image, and yours is excellent.  9</td>', 'This is a great shot, well composed & cropped to capture the "Don''t tread on me!" character of this awesome little machine.  Of course, adding the text would probably ruin the look of your image, but it would still be a terrific billboard with no text at all, and the word  "SUBARU" made just a little more prominent.  But this challenge is just about the image, and yours is excellent.  9', '2005-03-04 14:47:43.000000', NULL, 1),
(1207703, 150988, 30364, '<td valign="top">Terrific photograph!  Great composition and well executed.  Title''s no good for a billboard; too long.  "Go Wild. Dallas Zoo."  would do the trick nicely.  But that''s beside the point here; this is a very good billboard image.  9</td>', 'Terrific photograph!  Great composition and well executed.  Title''s no good for a billboard; too long.  "Go Wild. Dallas Zoo."  would do the trick nicely.  But that''s beside the point here; this is a very good billboard image.  9', '2005-03-04 14:54:50.000000', NULL, 1),
(1207766, 150747, 8860, '<td valign="top">Lovely image - would work well in the format (obviously with some text, URL and tourist board details!!). I particularly like the subtle clouds in the distance. The crop has crushedyour image though, but it was a 48hr challenge! <br/>: )</td>', 'Lovely image - would work well in the format (obviously with some text, URL and tourist board details!!). I particularly like the subtle clouds in the distance. The crop has crushedyour image though, but it was a 48hr challenge! : )', '2005-03-04 15:29:44.000000', NULL, 1),
(1207773, 150988, 8860, '<td valign="top">Apart from that prison-like, dull background, this is really impactful and would sell the zoo to me. Well composed and the space to the right would allow for text/logo very nicely.</td>', 'Apart from that prison-like, dull background, this is really impactful and would sell the zoo to me. Well composed and the space to the right would allow for text/logo very nicely.', '2005-03-04 15:31:20.000000', NULL, 1),
(1207776, 151038, 8860, '<td valign="top">It''s a bit biased against one brand but the idea is great. Crop is a bit loose though.</td>', 'It''s a bit biased against one brand but the idea is great. Crop is a bit loose though.', '2005-03-04 15:32:14.000000', NULL, 1),
(1207787, 150903, 8860, '<td valign="top">Like this treatment and it''s well composed. The gauze offers an evocative element and reminds one of being outside looking in - an effective conscience campaign.</td>', 'Like this treatment and it''s well composed. The gauze offers an evocative element and reminds one of being outside looking in - an effective conscience campaign.', '2005-03-04 15:36:13.000000', NULL, 1),
(1207793, 150853, 8860, '<td valign="top">Despite some unnecessary haloing of editng round his back this is a very well composed and dramatic shot. Great focus. You only really needed the ''Wanna Get High?'' part of the title though. The rest is just ugly! <br/>: )</td>', 'Despite some unnecessary haloing of editng round his back this is a very well composed and dramatic shot. Great focus. You only really needed the ''Wanna Get High?'' part of the title though. The rest is just ugly! : )', '2005-03-04 15:38:26.000000', NULL, 1),
(1207841, 151012, 8860, '<td valign="top">A couple of things: <br/>1. Nice reflection on the glasses and richness of tone.<br/>2. The crop is unfortunate. You could have enlarged the shades in the frame and cropped out the intrusive black area at the bottom. This would then leave the glasses as ''hero'' and leave just enough space for minimal text and logo. As it stands, the first thing you''re aware of is the table edge.<br/>3. shot is a touch noisy. You could try running it through neat Image (or equivalent) or converting to lab color mode in Photoshop and blurring the channels ''a'' and ''b'' until the noise is reduced. This leaves the definition (Lightness channel) intact.<br/> <br/>And lastly, Oakleys are unfortunately terribly made!! If you look at the stems you''ll probablly notice some poor spraying. They''re WAY over-priced compared to some much better brands (Adidas, RayBan) for equivalent outlay.</td>', 'A couple of things: 1. Nice reflection on the glasses and richness of tone.2. The crop is unfortunate. You could have enlarged the shades in the frame and cropped out the intrusive black area at the bottom. This would then leave the glasses as ''hero'' and leave just enough space for minimal text and logo. As it stands, the first thing you''re aware of is the table edge.3. shot is a touch noisy. You could try running it through neat Image (or equivalent) or converting to lab color mode in Photoshop and blurring the channels ''a'' and ''b'' until the noise is reduced. This leaves the definition (Lightness channel) intact. And lastly, Oakleys are unfortunately terribly made!! If you look at the stems you''ll probablly notice some poor spraying. They''re WAY over-priced compared to some much better brands (Adidas, RayBan) for equivalent outlay.', '2005-03-04 15:54:22.000000', NULL, 1),
