(1208445, 151023, 30959, '<td valign="top">Well done.. having the ocean at your door does not garuntee a good photo, it rarely behaves for you. Nice job.</td>', 'Well done.. having the ocean at your door does not garuntee a good photo, it rarely behaves for you. Nice job.', '2005-03-04 21:25:03.000000', NULL, 1),
(1208449, 150878, 30959, '<td valign="top">Love this picture,  clouds are a litle blown, but still.. love this pic.</td>', 'Love this picture,  clouds are a litle blown, but still.. love this pic.', '2005-03-04 21:26:07.000000', NULL, 1),
(1208450, 150502, 26733, '<td valign="top">Great billboard!</td>', 'Great billboard!', '2005-03-04 21:26:40.000000', NULL, 1),
(1208454, 151070, 30959, '<td valign="top">The goose is obscured by the weeds and much detail is missed by that, the building behind him is competing for attention as well. Perhaps move a bit off to the side would have given better composition, at worst he would have flown away and you would have gotten a wing shot!</td>', 'The goose is obscured by the weeds and much detail is missed by that, the building behind him is competing for attention as well. Perhaps move a bit off to the side would have given better composition, at worst he would have flown away and you would have gotten a wing shot!', '2005-03-04 21:28:55.000000', NULL, 1),
(1208457, 150617, 1031, '<td valign="top">I did that kind of stuff for years. Funny interpretation -- they are certainly all ears! : )</td>', 'I did that kind of stuff for years. Funny interpretation -- they are certainly all ears! : )', '2005-03-04 21:29:57.000000', NULL, 1),
(1208461, 150614, 30959, '<td valign="top">The fox is difficult to see as he is so small. I know they are hard to get a picture of but more of the fox would have given this more impact.</td>', 'The fox is difficult to see as he is so small. I know they are hard to get a picture of but more of the fox would have given this more impact.', '2005-03-04 21:30:58.000000', NULL, 1),
(1208463, 150653, 30959, '<td valign="top">Colors are vibrant, well placed in the field, nice focus. I didn''t care for the glass flowers, but as I sit here and look at the photo.. I''m bumping it up.</td>', 'Colors are vibrant, well placed in the field, nice focus. I didn''t care for the glass flowers, but as I sit here and look at the photo.. I''m bumping it up.', '2005-03-04 21:33:02.000000', NULL, 1),
(1208465, 151100, 20324, '<td valign="top">Good idea.  My favorite in this challenge. The car looks like a smiling face, simple and  nice. Well done :) 10.</td>', 'Good idea.  My favorite in this challenge. The car looks like a smiling face, simple and  nice. Well done :) 10.', '2005-03-04 21:33:35.000000', NULL, 1),
(1208481, 150730, 20324, '<td valign="top">Lovely picture, very nice composition. On my screen seems to be little to soft. B&amp;W works well here. (9)<br/></td>', 'Lovely picture, very nice composition. On my screen seems to be little to soft. B&W works well here. (9)', '2005-03-04 21:41:35.000000', NULL, 1),
(1208483, 150751, 20324, '<td valign="top">Nice color, good composition, I wish it would be sharper, I would like to see the text on the device clearly. (8)</td>', 'Nice color, good composition, I wish it would be sharper, I would like to see the text on the device clearly. (8)', '2005-03-04 21:41:52.000000', NULL, 1),
